package blockbranch.client.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;import blockbranch.realistic.*;
/** Connected native camera; the copied functional fixture retains its real blocks and consumed loot. */
public final class ReimaginedView {
 private static int trapTicks,trapPeak;private static BlockPos plate;private static boolean trapStarted;
 private static boolean opened,saving;private static volatile boolean posed;private static volatile int view;private static int settled;private static long began;private static volatile BlockPos anchor;private static final List<Object> records=new ArrayList<>();
 private static Path dir(){return Path.of(System.getProperty("blockbranch.reimaginedViewDir"));}
 public static void register(){ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||server.getPlayerList().getPlayers().isEmpty()||(posed&&view<4))return;try{
 if(view==4){var l=server.overworld();var player=server.getPlayerList().getPlayers().getFirst();if(!trapStarted){var holder=l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(ReimaginedStructures.key(2));var start=l.structureManager().getStartForStructure(holder.value(),l.getChunk(-701960>>4,270984>>4));var b=start.getBoundingBox();for(var p:BlockPos.betweenClosed(b.minX(),b.minY(),b.minZ(),b.maxX(),b.maxY(),b.maxZ()))if(l.getBlockState(p).is(net.minecraft.world.level.block.Blocks.STONE_PRESSURE_PLATE))plate=p.immutable();if(plate==null)throw new AssertionError("Original native plate");server.getCommands().performPrefixedCommand(server.createCommandSourceStack(),"tp "+player.getName().getString()+" "+(plate.getX()+.5)+" "+(plate.getY()+.1)+" "+(plate.getZ()+.5));player.getAbilities().flying=false;player.onUpdateAbilities();trapStarted=true;return;}trapPeak=Math.max(trapPeak,l.getEntitiesOfClass(net.minecraft.world.entity.item.PrimedTnt.class,new net.minecraft.world.phys.AABB(plate).inflate(20)).size());if(++trapTicks<200)return;if(trapPeak==0)throw new AssertionError("Connected player must activate native TNT trap");records.add(Map.of("nativeConnectedTrap",true,"primedTntPeak",trapPeak,"ticks",trapTicks));Files.writeString(dir().resolve("views.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(records));Files.writeString(dir().resolve("result.txt"),"PASS four native views and connected native pressure-plate/TNT interaction");view=5;return;}if(view>4)return;
  if(view==2){var l=server.overworld();var center=new BlockPos(228504,17,-267736);records.add(Map.of("cryptCoreBlockLight",l.getBrightness(net.minecraft.world.level.LightLayer.BLOCK,center.above()),"nativeSpidersNearCrypt",l.getEntitiesOfClass(net.minecraft.world.entity.monster.spider.Spider.class,new net.minecraft.world.phys.AABB(center).inflate(18)).size()));}
  int kind=view<2?1:2;int x=kind==1?228504:-701960,z=kind==1?-267736:270984;var level=server.overworld();var player=server.getPlayerList().getPlayers().getFirst();var source=server.createCommandSourceStack();var commands=server.getCommands();commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());player.getAbilities().flying=true;player.onUpdateAbilities();commands.performPrefixedCommand(source,"effect give "+player.getName().getString()+" minecraft:night_vision 100000 0 true");
  var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(ReimaginedStructures.key(kind));var start=level.structureManager().getStartForStructure(holder.value(),level.getChunk(x>>4,z>>4));if(start==null||!start.isValid())throw new AssertionError("Actual layout start");var piece=(ReimaginedLayoutPiece)start.getPieces().stream().filter(p->p instanceof ReimaginedLayoutPiece).findFirst().orElseThrow();
  int entry=piece.createTag(net.minecraft.world.level.levelgen.structure.pieces.StructurePieceSerializationContext.fromLevel(level)).getIntOr("EntryHeight",18);int[][] cameras={{-10,1,-11},{-14,1,2},{-4,entry+10,-33},{-7,-4,-8}};int[][] aims={{-10,2,10},{-17,1,-4},{4,entry-3,-18},{-7,-3,25}};var c=cameras[view];var a=aims[view];var camera=piece.local(c[0],c[1],c[2]);anchor=piece.local(a[0],a[1],a[2]);double cx=camera.getX()+.5,cy=camera.getY()+.2,cz=camera.getZ()+.5,dx=anchor.getX()+.5-cx,dz=anchor.getZ()+.5-cz,dy=anchor.getY()+.5-(cy+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));commands.performPrefixedCommand(source,"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+" "+yaw+" "+pitch);records.add(Map.of("kind",kind,"view",view,"camera",List.of(cx,cy,cz),"aim",anchor.toShortString(),"nightVision",true));blockbranch.Blockbranch.LOGGER.info("REIMAGINED_VIEW_POSED {}",view);posed=true;
 }catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("REIMAGINED_VIEW_FAIL",t);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}}});
 ClientTickEvents.END_CLIENT_TICK.register(client->{try{if(opened&&System.nanoTime()-began>600_000_000_000L){Files.writeString(dir().resolve("result.txt"),"FAIL view timeout");client.stop();return;}if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("ReimaginedReview",()->client.gui.setScreen(new TitleScreen()));return;}if(Files.exists(dir().resolve("result.txt"))){client.stop();return;}if(view>=4)return;if(!posed||client.level==null||client.player==null||saving)return;client.options.fov().set(75);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;var section=area.getRenderSectionAt(anchor);if(section==null||!section.getSectionMesh().hasRenderableLayers()){settled=0;return;}if(++settled<180)return;saving=true;String file=(view<2?"crypt":"pyramid")+"-"+(view%2+1)+".png";net.minecraft.client.Screenshot.grab(client.gameDirectory,file,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{view++;posed=false;saving=false;settled=0;}catch(Exception e){throw new RuntimeException(e);}}));}catch(Throwable t){try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}client.stop();}});
 }
}
